async function productFixture(status = ProductStatus.Published) { const db = createTestDb(); const category = await createCategory(db, { name: `Lifecycle ${crypto.randomUUID()}`, displayOrder: 0, isActive: true }); const product = await createProduct(db, { sku: `SKU-${crypto.randomUUID()}`, title: "Lifecycle Product", type: ProductType.UniqueItem, status, categoryId: category.id, stockQuantity: 1, purchaseCost: 25, priceEur: 100, customsWarning: false, isFeatured: false, allowMakeOffer: false, allowCashOnDelivery: false, showInArchiveAfterSale: false }); return { db, product }; }

describe("Sprint 149 Checkpoint 1 lifecycle foundation", () => {
  it("keeps ProductStatus unchanged and classifies listing terminal states case-insensitively", () => { expect(Object.values(ProductStatus)).not.toContain("paused"); for (const value of ["ended", "INACTIVE", "Sold", "closed"]) expect(isTerminalExternalListingStatus(value)).toBe(true); for (const value of ["active", "unknown", "", "ending"]) expect(isTerminalExternalListingStatus(value)).toBe(false); });

  it("fresh SQLite creates both structures and database-enforces idempotency and one processing operation", () => { const sqlite = new Database(":memory:"); ensureSchema(sqlite); expect((sqlite.prepare("PRAGMA table_info(products)").all() as any[]).some((row) => row.name === "sale_paused_at")).toBe(true); expect(sqlite.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='product_lifecycle_operations'").get()).toBeTruthy(); const insert = sqlite.prepare("INSERT INTO product_lifecycle_operations(id,product_id,action,status,previous_product_status,target_snapshot,target_results,actor_admin_user_id,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)"); const row = (id:string,p:string,s:string,k:string) => [id,p,"pause",s,"published","[]","[]","actor",k,"2026-01-01","2026-01-01"]; insert.run(...row("1","p","processing","key-1")); expect(() => insert.run(...row("2","q","succeeded","key-1"))).toThrow(); expect(() => insert.run(...row("3","p","processing","key-3"))).toThrow(); expect(() => insert.run(...row("4","p","succeeded","key-4"))).not.toThrow(); sqlite.close(); });

  it("additive SQLite upgrade preserves Product/ExternalListing data and is rerunnable", () => { const sqlite = new Database(":memory:"); ensureSchema(sqlite); sqlite.exec("INSERT INTO categories(id,name,slug,display_order,is_active,created_at,updated_at) VALUES('c','C','c',0,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP); INSERT INTO products(id,sku,title,slug,type,status,category_id,stock_quantity,price_eur,customs_warning,is_featured,allow_make_offer,allow_cash_on_delivery,show_in_archive_after_sale,created_at,updated_at) VALUES('p','SKU','P','p','unique_item','draft','c',1,10,0,0,0,0,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP); INSERT INTO marketplace_connections(id,channel,account_label,status,created_at,updated_at) VALUES('conn','ebay','A','connected',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP); INSERT INTO external_listings(id,product_id,channel,connection_id,external_listing_id,external_status,payload_snapshot,published_at,updated_at) VALUES('ext','p','ebay','conn','remote','active','{}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);"); sqlite.exec("DROP INDEX idx_product_lifecycle_one_processing; DROP INDEX idx_product_lifecycle_product; DROP TABLE product_lifecycle_operations; ALTER TABLE products DROP COLUMN sale_paused_at;"); ensureSchema(sqlite); ensureSchema(sqlite); expect(sqlite.prepare("SELECT sku FROM products WHERE id='p'").get()).toEqual({ sku:"SKU" }); expect(sqlite.prepare("SELECT external_listing_id FROM external_listings WHERE id='ext'").get()).toEqual({ external_listing_id:"remote" }); expect((sqlite.prepare("PRAGMA index_list(product_lifecycle_operations)").all() as any[]).map((row)=>row.name)).toEqual(expect.arrayContaining(["idx_product_lifecycle_product","idx_product_lifecycle_one_processing"])); sqlite.close(); });

  it("atomically pauses locally, preserves Product/inventory/history, snapshots every non-terminal target, and performs no network call", async () => { const { db, product } = await productFixture(); const before = await getProductById(db, product.id); await db.insert(schema.productPhotos).values({ id:"photo", productId:product.id, url:"/photo.jpg", thumbnailUrl:"/thumb.jpg", filename:"photo.jpg", mimeType:"image/jpeg", sizeBytes:1, width:1, height:1, sortOrder:0, isPrimary:true, processingStatus:"Ready", createdAt:"2026-01-01", updatedAt:"2026-01-01" }); for (const [id,channel] of [["conn-a",PublishChannel.Ebay],["conn-c",PublishChannel.Etsy],["conn-d",PublishChannel.Ebay],["conn-e",PublishChannel.Etsy]] as const) await db.insert(schema.marketplaceConnections).values({id,channel,accountLabel:id,status:"connected",createdAt:"2026-01-01",updatedAt:"2026-01-01"}); const rows = [["a",PublishChannel.Ebay,"conn-a","remote-a","active"],["b",PublishChannel.Ebay,"conn-a","remote-b","UNKNOWN"],["c",PublishChannel.Etsy,"conn-c","remote-c","live"],["d",PublishChannel.Ebay,"conn-d","remote-d","ENDED"],["e",PublishChannel.Etsy,"conn-e","remote-e","sold"]] as const; for (const [id,channel,connectionId,externalListingId,externalStatus] of rows) await db.insert(schema.externalListings).values({ id,productId:product.id,channel,connectionId,externalListingId,externalStatus,payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01" }); const counts = { movements:(await db.select().from(schema.stockMovements)).length, reservations:(await db.select().from(schema.stockReservations)).length, photos:(await db.select().from(schema.productPhotos)).length, jobs:(await db.select().from(schema.publishJobs)).length }; const fetchSpy=vi.spyOn(globalThis,"fetch"); const result=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"pause-key"}); const after=await getProductById(db,product.id); expect(after.salePausedAt).toBeTruthy(); expect(after.status).toBe(before.status); expect(after.stockQuantity).toBe(before.stockQuantity); expect(after.sku).toBe(before.sku); expect(after.purchaseCost).toBe(before.purchaseCost); expect((await db.select().from(schema.stockMovements))).toHaveLength(counts.movements); expect((await db.select().from(schema.stockReservations))).toHaveLength(counts.reservations); expect((await db.select().from(schema.productPhotos))).toHaveLength(counts.photos); expect((await db.select().from(schema.publishJobs))).toHaveLength(counts.jobs); expect(fetchSpy).not.toHaveBeenCalled(); fetchSpy.mockRestore(); const external=result.operation.targetSnapshot.filter((target)=>target.kind==="external"); expect(external.map((target)=>target.internalListingId)).toEqual(["a","b","c"]); expect(external.find((target)=>target.internalListingId==="a")).toMatchObject({externalListingId:"remote-a",connectionId:"conn-a",previousExternalStatus:"active"}); expect(result.productUpdatedAtBefore).toBe(before.updatedAt); expect(result.productUpdatedAtAfter).toBe(after.updatedAt); expect(result.productUpdatedAtAfter).not.toBe(result.productUpdatedAtBefore); expect(result.operation.actorAdminUserId).toBe("admin"); });

  it("same idempotency key reuses one operation and does not mutate Product again", async () => { const {db,product}=await productFixture(); const first=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"same-key"}); const second=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"same-key"}); expect(second.operation.id).toBe(first.operation.id); expect((await db.select().from(schema.productLifecycleOperations))).toHaveLength(1); expect(second.productUpdatedAtBefore).toBe(second.productUpdatedAtAfter); });

  it("PostgreSQL migration is next and declares timestamptz, JSONB and both uniqueness invariants", () => { const files=fs.readdirSync(new URL("../src/db/postgres-migrations",import.meta.url)).filter((file)=>file.endsWith(".sql")).sort(); expect(files.at(-1)).toBe("0019_sprint149_product_lifecycle.sql"); const sql=fs.readFileSync(new URL("../src/db/postgres-migrations/0019_sprint149_product_lifecycle.sql",import.meta.url),"utf8"); expect(sql).toContain("sale_paused_at timestamptz"); expect(sql.match(/jsonb/g)?.length).toBe(2); expect(sql).toContain("idempotency_key text NOT NULL UNIQUE"); expect(sql).toContain("WHERE status = 'processing'"); });

  it("processes deterministically and incrementally, continues after failure, uses original tokens, and replay resumes only failure", async()=>{process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,8).toString("base64");const{db,product}=await productFixture(ProductStatus.Draft);for(const[id,channel,token]of[["ca",PublishChannel.Ebay,"token-a"],["ce",PublishChannel.Etsy,"token-e"]]as const)await db.insert(schema.marketplaceConnections).values({id,channel,accountLabel:id,status:"connected",encryptedAccessToken:encryptCredential(token),tokenExpiresAt:new Date(Date.now()+60_000).toISOString(),createdAt:"2026-01-01",updatedAt:"2026-01-01"});for(const[id,channel,connectionId]of[["a",PublishChannel.Ebay,"ca"],["b",PublishChannel.Ebay,"ca"],["c",PublishChannel.Etsy,"ce"]]as const)await db.insert(schema.externalListings).values({id,productId:product.id,channel,connectionId,externalListingId:`remote-${id}`,externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const before={stock:product.stockQuantity,movements:(await db.select().from(schema.stockMovements)).length,reservations:(await db.select().from(schema.stockReservations)).length};const calls:string[]=[],tokens:string[]=[];let firstFails=true;const adapter={endListing:async(token:string,id:string)=>{tokens.push(token);calls.push(`end:${id}`);if(id==="remote-a"&&firstFails)throw new Error("temporary failure");if(id==="remote-b"){const[op]=await db.select().from(schema.productLifecycleOperations);const results=JSON.parse(op.targetResults);expect(results.find((t:any)=>t.internalListingId==="a").status).toBe("failed");}return{externalListingId:id,externalStatus:"ended"};},fetchListingStatus:async(token:string,id:string)=>{tokens.push(token);calls.push(`fetch:${id}`);return{externalListingId:id,externalStatus:"unknown"};},normalizeError:()=>({type:"Temporary",message:"temporary",retryable:true})}as any as MarketplaceAdapter;const first=await pauseProduct(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"pause-process"},()=>adapter);expect(calls).toEqual(["end:remote-a","fetch:remote-a","end:remote-b","end:remote-c"]);expect(tokens).toEqual(["token-a","token-a","token-a","token-e"]);expect(first.operation.status).toBe("partially_failed");expect((await getProductById(db,product.id)).salePausedAt).toBeTruthy();firstFails=false;calls.length=0;const replay=await pauseProduct(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"pause-process"},()=>adapter);expect(replay.operation.id).toBe(first.operation.id);expect(calls).toEqual(["end:remote-a"]);expect(replay.operation.status).toBe("succeeded");expect((await db.select().from(schema.externalListings)).every((row)=>row.externalStatus==="ended")).toBe(true);expect((await getProductById(db,product.id)).stockQuantity).toBe(before.stock);expect(await db.select().from(schema.stockMovements)).toHaveLength(before.movements);expect(await db.select().from(schema.stockReservations)).toHaveLength(before.reservations);});

  it("never falls back from missing, wrong-channel, disconnected, or expired original connections",async()=>{process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,7).toString("base64");for(const kind of ["tokenless","wrong","disconnected","expired"]){const{db,product}=await productFixture(ProductStatus.Draft);await db.insert(schema.marketplaceConnections).values({id:"alternate",channel:PublishChannel.Ebay,accountLabel:"alternate",status:"connected",encryptedAccessToken:encryptCredential("alternate-token"),createdAt:"2026-01-01",updatedAt:"2026-01-01"});await db.insert(schema.marketplaceConnections).values({id:"original",channel:kind==="wrong"?PublishChannel.Etsy:PublishChannel.Ebay,accountLabel:"original",status:kind==="disconnected"?"revoked":"connected",encryptedAccessToken:kind==="tokenless"?undefined:encryptCredential("original-token"),tokenExpiresAt:kind==="expired"?new Date(Date.now()-1000).toISOString():undefined,createdAt:"2026-01-01",updatedAt:"2026-01-01"});await db.insert(schema.externalListings).values({id:"listing",productId:product.id,channel:PublishChannel.Ebay,connectionId:"original",externalListingId:"remote",externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const end=vi.fn(),operation=await pauseProduct(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:`key-${kind}`},()=>({endListing:end,normalizeError:()=>({type:"Permanent",message:"permanent",retryable:false})}as any));expect(end).not.toHaveBeenCalled();expect(operation.operation.targetResults[0].status).toBe("failed");expect(operation.operation.targetResults[0].retryable).toBe(false);expect((await getProductById(db,product.id)).salePausedAt).toBeTruthy();}});

  it("honors deterministic fresh/stale leases and stale reconciliation order",async()=>{expect(marketplacePauseLeaseMs(1)).toBe(60_000);expect(marketplacePauseLeaseMs(30_000)).toBe(90_000);const now=new Date("2026-01-01T00:02:00.000Z"),fresh={status:"processing",processingStartedAt:"2026-01-01T00:01:00.000Z"}as any,stale={status:"processing",processingStartedAt:"2026-01-01T00:00:59.999Z"}as any;expect(isProcessingTargetStale(fresh,now.getTime(),60_000)).toBe(false);expect(isProcessingTargetStale(stale,now.getTime(),60_000)).toBe(true);process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,6).toString("base64");const{db,product}=await productFixture(ProductStatus.Draft);await db.insert(schema.marketplaceConnections).values({id:"conn",channel:PublishChannel.Ebay,accountLabel:"conn",status:"connected",encryptedAccessToken:encryptCredential("token"),createdAt:"2026-01-01",updatedAt:"2026-01-01"});await db.insert(schema.externalListings).values({id:"listing",productId:product.id,channel:PublishChannel.Ebay,connectionId:"conn",externalListingId:"remote",externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const begun=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"lease-key"}),repo=createProductLifecycleRepository(db),end=vi.fn(async()=>({externalListingId:"remote",externalStatus:"ended"})),fetch=vi.fn(async()=>({externalListingId:"remote",externalStatus:"ended"})),adapter={endListing:end,fetchListingStatus:fetch,normalizeError:()=>({type:"Temporary",message:"temporary",retryable:true})}as any;let results=begun.operation.targetResults.map((target)=>({...target,status:"processing"as const,processingStartedAt:"2026-01-01T00:01:30.000Z"}));await repo.update(begun.operation.id,{targetResults:results});await processPauseOperation(db,(await repo.getById(begun.operation.id))!,()=>adapter,()=>now);expect(fetch).not.toHaveBeenCalled();expect(end).not.toHaveBeenCalled();results=results.map((target)=>({...target,processingStartedAt:"2026-01-01T00:00:00.000Z"}));await repo.update(begun.operation.id,{targetResults:results});await processPauseOperation(db,(await repo.getById(begun.operation.id))!,()=>adapter,()=>now);expect(fetch).toHaveBeenCalledTimes(1);expect(end).not.toHaveBeenCalled();expect((await repo.getById(begun.operation.id))!.targetResults[0].status).toBe("succeeded");});

  it("explicit Retry skips success, processes retryable failure, preserves Pause and inventory",async()=>{process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,5).toString("base64");const{db,product}=await productFixture(ProductStatus.Draft);await db.insert(schema.marketplaceConnections).values({id:"conn",channel:PublishChannel.Ebay,accountLabel:"conn",status:"connected",encryptedAccessToken:encryptCredential("token"),createdAt:"2026-01-01",updatedAt:"2026-01-01"});for(const id of ["a","b"])await db.insert(schema.externalListings).values({id,productId:product.id,channel:PublishChannel.Ebay,connectionId:"conn",externalListingId:id,externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const begun=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"retry-key"}),repo=createProductLifecycleRepository(db),results=begun.operation.targetResults.map((target,index)=>({...target,status:index===0?"succeeded"as const:"failed"as const,retryable:index===0?undefined:true}));await repo.update(begun.operation.id,{targetResults:results,status:"partially_failed"});const end=vi.fn(async(_token:string,id:string)=>({externalListingId:id,externalStatus:"ended"}));const movementCount=(await db.select().from(schema.stockMovements)).length,reservationCount=(await db.select().from(schema.stockReservations)).length;const retried=await retryPauseOperation(db,product.id,begun.operation.id,()=>({endListing:end,fetchListingStatus:vi.fn(),normalizeError:()=>({type:"Temporary",message:"temporary",retryable:true})}as any));expect(end).toHaveBeenCalledTimes(1);expect(end.mock.calls[0][1]).toBe("b");expect(retried.status).toBe("succeeded");expect((await getProductById(db,product.id)).salePausedAt).toBeTruthy();expect(await db.select().from(schema.stockMovements)).toHaveLength(movementCount);expect(await db.select().from(schema.stockReservations)).toHaveLength(reservationCount);});

  it("database claim permits only one concurrent adapter call and stale non-terminal recovery fetches before ending",async()=>{process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,4).toString("base64");const{db,product}=await productFixture(ProductStatus.Draft);await db.insert(schema.marketplaceConnections).values({id:"conn",channel:PublishChannel.Ebay,accountLabel:"conn",status:"connected",encryptedAccessToken:encryptCredential("token"),createdAt:"2026-01-01",updatedAt:"2026-01-01"});await db.insert(schema.externalListings).values({id:"listing",productId:product.id,channel:PublishChannel.Ebay,connectionId:"conn",externalListingId:"remote",externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const begun=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"concurrent-key"});let release!:()=>void;const gate=new Promise<void>((resolve)=>release=resolve),end=vi.fn(async()=>{await gate;return{externalListingId:"remote",externalStatus:"ended"}}),adapter={endListing:end,fetchListingStatus:vi.fn(),normalizeError:()=>({type:"Temporary",message:"temporary",retryable:true})}as any;const first=processPauseOperation(db,begun.operation,()=>adapter),second=processPauseOperation(db,begun.operation,()=>adapter);await new Promise((resolve)=>setTimeout(resolve,10));expect(end).toHaveBeenCalledTimes(1);release();await Promise.all([first,second]);const repo=createProductLifecycleRepository(db),current=(await repo.getById(begun.operation.id))!,stale=current.targetResults.map((target)=>({...target,status:"processing"as const,processingStartedAt:"2020-01-01T00:00:00.000Z"}));await repo.update(current.id,{targetResults:stale,status:"processing",completedAt:null});const order:string[]=[],fetch=vi.fn(async()=>{order.push("fetch");return{externalListingId:"remote",externalStatus:"active"}}),endAgain=vi.fn(async()=>{order.push("end");return{externalListingId:"remote",externalStatus:"ended"}});await processPauseOperation(db,(await repo.getById(current.id))!,()=>({...adapter,fetchListingStatus:fetch,endListing:endAgain}as any));expect(order).toEqual(["fetch","end"]);});

  it("rejects every ordinary publish channel and reports batch failures while paused",async()=>{const{db,product}=await productFixture();await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"guard-pause"});for(const channel of [PublishChannel.NoctellaWeb,PublishChannel.Ebay,PublishChannel.Etsy])await expect(executePublish(db,product.id,channel,`guard-${channel}`)).rejects.toThrow(/Paused Product/);const result=await executePublishBatch(db,product.id,[PublishChannel.NoctellaWeb,PublishChannel.Ebay,PublishChannel.Etsy],(await getProductById(db,product.id)).updatedAt);expect(result.results).toHaveLength(3);expect(result.results.every(item=>item.outcome==="failed"&&item.error?.message.includes("Paused Product"))).toBe(true);});

  it("derives only snapshotted channels, rejects ambiguous accounts, and fully relists Web with current data",async()=>{const{db,product}=await productFixture();await db.update(schema.products).set({wooProductName:"Current title",wooShortDescription:"Current short",wooLongDescription:"Current long"});await db.insert(schema.productPhotos).values({id:"relist-photo",productId:product.id,url:"/photo.jpg",thumbnailUrl:"/thumb.jpg",filename:"photo.jpg",mimeType:"image/jpeg",sizeBytes:1,width:1,height:1,sortOrder:0,isPrimary:true,processingStatus:"Ready",createdAt:"2026-01-01",updatedAt:"2026-01-01"});await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"web-pause"});const operation=await beginProductRelist(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"web-relist"});expect(operation.targetSnapshot.map(t=>t.channel)).toEqual([PublishChannel.NoctellaWeb]);const before=(await getProductById(db,product.id)).updatedAt,result=await relistProduct(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:"web-relist"});expect(result.operation.status).toBe("succeeded");expect((await getProductById(db,product.id)).salePausedAt).toBeUndefined();expect(result.productUpdatedAtAfter).not.toBe(before);expect(await db.select().from(schema.stockMovements)).toHaveLength(1);expect(await db.select().from(schema.stockReservations)).toHaveLength(0);
    const other=await productFixture(ProductStatus.Draft);for(const id of ["c1","c2"])await other.db.insert(schema.marketplaceConnections).values({id,channel:PublishChannel.Ebay,accountLabel:id,status:"connected",createdAt:"2026-01-01",updatedAt:"2026-01-01"});for(const id of ["c1","c2"])await other.db.insert(schema.externalListings).values({id:`l-${id}`,productId:other.product.id,channel:PublishChannel.Ebay,connectionId:id,externalListingId:`r-${id}`,externalStatus:"active",payloadSnapshot:"{}",publishedAt:"2026-01-01",updatedAt:"2026-01-01"});const pause=await beginProductPause(other.db,{productId:other.product.id,actorAdminUserId:"admin",idempotencyKey:"amb-pause"}),repo=createProductLifecycleRepository(other.db);await repo.update(pause.operation.id,{targetResults:pause.operation.targetResults.map(t=>({...t,status:"succeeded"})),status:"succeeded",completedAt:new Date().toISOString()});await expect(beginProductRelist(other.db,{productId:other.product.id,actorAdminUserId:"admin",idempotencyKey:"amb-relist"})).rejects.toThrow(/manual connection/);});
});

async function externalRelistFixture(key:string){
  process.env.MARKETPLACE_CREDENTIAL_ENCRYPTION_KEY=Buffer.alloc(32,9).toString("base64");
  const {db,product}=await productFixture(ProductStatus.Draft);
  await db.update(schema.products).set({ebayTitle:"Current eBay title",ebayDescription:"Current description",ebayCategory:"123",ebayListingPriceEur:110});
  await db.insert(schema.productPhotos).values({id:`photo-${key}`,productId:product.id,url:"/photo.jpg",thumbnailUrl:"/thumb.jpg",filename:"photo.jpg",mimeType:"image/jpeg",sizeBytes:1,width:1,height:1,sortOrder:0,isPrimary:true,processingStatus:"Ready",createdAt:"2026-01-01",updatedAt:"2026-01-01"});
  for(const [id,token] of [["original","token-original"],["alternate","token-alternate"]] as const)await db.insert(schema.marketplaceConnections).values({id:`${id}-${key}`,channel:PublishChannel.Ebay,accountLabel:`${id}-${key}`,status:"connected",encryptedAccessToken:encryptCredential(token),createdAt:"2026-01-01",updatedAt:"2026-01-01"});
  await db.insert(schema.externalListings).values({id:`old-${key}`,productId:product.id,channel:PublishChannel.Ebay,connectionId:`original-${key}`,externalListingId:`old-remote-${key}`,externalStatus:"active",payloadSnapshot:JSON.stringify({title:"stale title"}),publishedAt:"2026-01-01",updatedAt:"2026-01-01"});
  const pause=await beginProductPause(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:`pause-${key}`}),repo=createProductLifecycleRepository(db);
  await repo.updateExternalListingStatus(product.id,`old-${key}`,"ended");await repo.update(pause.operation.id,{targetResults:pause.operation.targetResults.map(t=>({...t,status:"succeeded"})),status:"succeeded",completedAt:new Date().toISOString()});
  const operation=await beginProductRelist(db,{productId:product.id,actorAdminUserId:"admin",idempotencyKey:`relist-${key}`});
  return{db,product,operation,repo,originalConnectionId:`original-${key}`};
}
const relistAdapter=(createListing:any)=>({createListing,normalizeError:(error:any)=>({type:"Temporary",message:error?.message??"failed",retryable:true})} as any as MarketplaceAdapter);

